{
  "findings": [
    {
      "check_id": "CKV_AWS_79",
      "title": "Ensure Instance Metadata Service Version 1 is not enabled",
      "resource": "aws_launch_template.web_app",
      "severity": "MEDIUM",
      "explanation": "Instance Metadata Service Version 1 (IMDSv1) is less secure than IMDSv2 because it is vulnerable to SSRF attacks. IMDSv2 should be enforced to enhance security."
    },
    {
      "check_id": "UNKNOWN",
      "title": "Hardcoded sensitive information in user_data",
      "resource": "aws_launch_template.web_app",
      "severity": "HIGH",
      "explanation": "Hardcoding sensitive information like API keys and database passwords in user_data is a security risk. These values should be securely retrieved from a secrets manager or environment variables."
    }
  ],
  "patched_code": "resource "aws_launch_template" "web_app" {
  name_prefix   = "automated-employee-onboarding-platform-lt-web-"
  image_id      = data.aws_ami.ubuntu.id
  instance_type = var.instance_type
  key_name      = var.key_pair_name
  vpc_security_group_ids = [aws_security_group.web_app.id]
  metadata_options {
    http_tokens = "required"
  }
  user_data = base64encode(<<-EOF
              # Sensitive information should be retrieved securely
              export DATABASE_PASSWORD=$(aws secretsmanager get-secret-value --secret-id db_password --query SecretString --output text)
              export API_KEY=$(aws secretsmanager get-secret-value --secret-id api_key --query SecretString --output text)
              apt-get update
              apt-get install -y nginx nodejs npm
              systemctl start nginx
              systemctl enable nginx
              EOF
  )
  tag_specifications {
    resource_type = "instance"
  }
}",
  "fix_summary": "Enforced IMDSv2 by adding the `metadata_options` block with `http_tokens` set to `required`. Replaced hardcoded sensitive information in `user_data` with secure retrieval commands using AWS Secrets Manager."
}
